// Loads the generated component pages at build time and renders them to HTML for the docs routes.
// The markdown is generated by `scripts/gen-docs.mjs`, so it is our own content and can be rendered
// without sanitising.
import { marked } from 'marked';

export interface VariationSpec {
	prop: string;
	values: string[];
}

/** Which families get a generated variation grid, and for which props. */
const variations = (
	import.meta.glob('../../docs/examples.json', { eager: true, import: 'default' }) as Record<
		string,
		Record<string, VariationSpec[]>
	>
)['../../docs/examples.json'] ?? {};

export interface DocPage {
	slug: string;
	title: string;
	description: string;
	group: string;
	variations: VariationSpec[];
	html: string;
	/** `h2`/`h3` ids for an in-page table of contents. */
	headings: { id: string; text: string; level: 2 | 3 }[];
}

const raw = import.meta.glob('../../docs/components/*.md', {
	query: '?raw',
	import: 'default',
	eager: true
}) as Record<string, string>;

const slugify = (value: string) =>
	value
		.toLowerCase()
		.replace(/[^a-z0-9\s-]/g, '')
		.trim()
		.replace(/\s+/g, '-');

function frontmatter(source: string): { data: Record<string, string>; body: string } {
	const match = /^---\n([\s\S]*?)\n---\n?/.exec(source);
	if (!match) return { data: {}, body: source };
	const data: Record<string, string> = {};
	for (const line of match[1].split('\n')) {
		const pair = /^([a-zA-Z]+):\s*(.*)$/.exec(line);
		if (pair) data[pair[1]] = pair[2].replace(/^['"]|['"]$/g, '');
	}
	return { data, body: source.slice(match[0].length) };
}

function slugifyHeadings(html: string) {
	const headings: DocPage['headings'] = [];
	const withIds = html.replace(/<h([23])>([\s\S]*?)<\/h\1>/g, (_, level, inner) => {
		const text = inner.replace(/<[^>]+>/g, '');
		const id = slugify(text);
		headings.push({ id, text, level: Number(level) as 2 | 3 });
		return `<h${level} id="${id}">${inner}</h${level}>`;
	});
	return { html: withIds, headings };
}

/** Group order mirrors `docs/components/README.md`, which mirrors the gallery. */
const GROUPS: Record<string, string> = {};
for (const [group, families] of Object.entries({
	Pure: ['alert', 'aspect-ratio', 'avatar', 'badge', 'bleed', 'breadcrumbs', 'button', 'card', 'close-button', 'container', 'empty', 'heading', 'highlight', 'image', 'input', 'input-group', 'kbd', 'list', 'marquee', 'progress-circular', 'progress-linear', 'separator', 'simple-grid', 'skeleton', 'spinner', 'stack', 'swap', 'table', 'tag', 'text', 'textarea', 'typeset'],
	Behavioral: ['accordion', 'angle-slider', 'checkbox', 'clipboard', 'collapsible', 'editable', 'field', 'fieldset', 'native-select', 'number-input', 'pagination', 'password-input', 'pin-input', 'qr-code', 'radio-group', 'rating-group', 'scroll-area', 'segment-group', 'signature-pad', 'slider', 'splitter', 'steps', 'switch', 'tabs', 'tags-input', 'timer', 'toggle', 'toggle-group'],
	Overlays: ['command-palette', 'dialog', 'drawer', 'floating-panel', 'hover-card', 'lightbox', 'menu', 'navigation-menu', 'popover', 'sidebar', 'split-button', 'toast', 'tooltip', 'tour'],
	Collections: ['combobox', 'json-tree-view', 'listbox', 'select', 'toc', 'tree-view'],
	'Data and media': ['carousel', 'color-picker', 'date-input', 'date-picker', 'file-upload', 'image-cropper']
})) {
	for (const family of families) GROUPS[family] = group;
}

export const pages: DocPage[] = Object.entries(raw)
	.map(([file, source]) => {
		const slug = file.split('/').at(-1)!.replace(/\.md$/, '');
		if (slug === 'README') return null;
		const { data, body } = frontmatter(source);
		const rendered = marked.parse(body, { async: false, gfm: true }) as string;
		const { html, headings } = slugifyHeadings(rendered);
		return {
			slug,
			title: data.title ?? slug,
			description: data.description ?? '',
			group: GROUPS[slug] ?? 'Other',
			variations: variations[slug] ?? [],
			html,
			headings
		} satisfies DocPage;
	})
	.filter((page): page is DocPage => page !== null);

// Explicit order, so the sidebar and the landing grid read like the gallery rather than like
// whatever order the filesystem happened to return.
const GROUP_ORDER = ['Pure', 'Behavioral', 'Overlays', 'Collections', 'Data and media', 'Other'];

export const groups = GROUP_ORDER.filter((group) => pages.some((page) => page.group === group));

export const byGroup = groups.map((group) => ({
	group,
	pages: pages.filter((page) => page.group === group)
}));

export const bySlug = new Map(pages.map((page) => [page.slug, page]));

export const order = pages.map((page) => page.slug);

export function neighbours(slug: string) {
	const index = order.indexOf(slug);
	return {
		previous: index > 0 ? bySlug.get(order[index - 1]) : undefined,
		next: index >= 0 && index < order.length - 1 ? bySlug.get(order[index + 1]) : undefined
	};
}
